use verus::*;

verus! {
    /// The set of all values appearing in nums[0..end]
    #[verifier(publish)]
    spec fn set_of_slice(nums: &Vec<i32>, end: nat) -> Set<i32> {
        Set::new(|x: i32| exists |k: nat| k < end && nums[k] == x)
    }

    /// The number of distinct values in nums[0..end]
    #[verifier(publish)]
    spec fn distinct_count_slice(nums: &Vec<i32>, end: nat) -> nat {
        set_of_slice(nums, end).len()
    }

    /// The number of distinct values in the entire vector
    #[verifier(publish)]
    spec fn distinct_count(nums: &Vec<i32>) -> nat {
        set_of_slice(nums, nums.len()).len()
    }

    /// Lemma: in a non‐decreasing array, if nums[i] > nums[i−1], then
    /// nums[i] is not in the prefix 0..i, so the prefix set grows by 1.
    proof fn lemma_strict_step(
        nums: &Vec<i32>,
        i: nat
    )
        requires
            1 <= i && i < nums.len(),
            // sorted prefix
            forall |j: nat| j + 1 < nums.len() ==> nums[j] <= nums[j+1],
            // strict increase at the boundary
            nums[i-1] < nums[i]
        ensures
            distinct_count_slice(nums, i + 1)
            ==
            distinct_count_slice(nums, i) + 1
    {
        // First show nums[i] is not in set_of_slice(nums, i)
        assert forall |k: nat| k < i ==> nums[k] < nums[i] by {
            // from sortedness: nums[k] <= nums[i-1] < nums[i]
            assert(nums[k] <= nums[i-1]);
            assert(nums[i-1] < nums[i]);
            assert(nums[k] < nums[i]);
        }
        assert(! set_of_slice(nums, i).contains(nums[i]));

        // Then by set‐insertion on an absent element:
        // set_of_slice(nums, i+1) == set_of_slice(nums, i).insert(nums[i]),
        // so cardinalities differ by exactly 1.
        assert(set_of_slice(nums, i+1) == set_of_slice(nums, i).insert(nums[i]));
        assert(set_of_slice(nums, i+1).len() == set_of_slice(nums, i).len() + 1);
        // QED
    }

    /// Counts how many distinct values appear in a non‐decreasing Vec<i32>.
    fn remove_duplicates(nums: &Vec<i32>) -> (result: usize)
        requires
            // nums is sorted non‐decreasing
            forall |i: nat, j: nat| i < j && j < nums.len() ==> nums[i] <= nums[j]
        ensures
            // we never overcount
            result <= nums.len(),
            // and we exactly match the spec‐function
            result == distinct_count(nums)
    {
        let n: usize = nums.len();
        let mut i: usize = 0;
        let mut c: usize = 0;
        // Loop over i = 0..n, maintaining:
        //   c == distinct_count_slice(nums, i)
        //   0 <= c <= i
        while i < n
            invariant
                i <= n,
                c <= i,
                c == distinct_count_slice(nums, i),
            decreases n - i
        {
            if i == 0 {
                // first element always contributes one distinct
                c = 1;
            } else if nums[i] > nums[i-1] {
                // strictly bigger than predecessor ⇒ new distinct
                lemma_strict_step(nums, i);
                c = c + 1;
            } else {
                // nums[i] == nums[i-1], no change in distinct count
            }
            i = i + 1;
        }
        result = c;
    }
}